"""Render complete provisional choices; never alter the native BOM."""
from pathlib import Path
import json, html
from collections import Counter
R=Path(__file__).resolve().parents[1]
p=json.loads((R/'evidence/capacitor_value_review_20261015.json').read_text(encoding='utf-8'))
model=json.loads((R/'evidence/reconstruction.json').read_text(encoding='utf-8'))
current_nets={e:n['net'] for n in model['nets'] for e in n['endpoints']}
e=html.escape
b=p['antenna_design_example']
groups=[('REFERENCE_STARTING_VALUE','12 supply capacitors: replacement starting choices'),('SIGNAL_CANDIDATE','17 signal and timing capacitors: function-based trials'),('RF_DESIGN_SEED','15 antenna capacitors: a conditional design example')]
def table(head,rows):
    return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def section(title,body): return '<section><h2>'+title+'</h2>'+body+'</section>'
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PetSafe - complete capacitor candidates</title><style>
body{font:16px/1.5 system-ui;color:#193d35;background:#edf3ef;max-width:1500px;margin:24px auto;padding:0 20px}a{color:#006c61}section,.note{background:white;padding:24px;margin:20px 0;border:1px solid #bfd2c7;border-radius:9px}.note{border-left:5px solid #b87516}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;vertical-align:top;padding:12px;border-bottom:1px solid #cbdad0}th{background:#e1ece5}.scroll{overflow-x:auto}small{color:#50685c}li{margin:8px 0}code{background:#e1ece5;padding:3px}h1{font-size:34px}nav{display:flex;gap:20px;flex-wrap:wrap}svg{max-width:800px;width:100%;height:auto}.caption{font-size:14px;color:#50685c}@media print{body{background:white;font-size:11px}table{font-size:10px}section{padding:4px}tr{break-inside:avoid}}
</style><nav><a href="../index.html">Schematic overview</a><a href="FINISHING_CHECKLIST.html#V01">Remaining questions</a><a href="FINISHING_MEASUREMENTS.html">Recorded readings</a></nav><h1>A value proposal for every capacitor</h1>'''
page+=f'<p>Based on schematic {e(p["schematic_revision"])} | {e(p["review_edition"])} | 51 capacitor entries accounted for</p>'
page+='<div class="note"><b>All 44 estimates remain applied to the native schematic, marked with an asterisk.</b> These are engineering choices, not recovered factory values. C5, six DNP options and recorded values are preserved. <b>Receiver correction v0.9.46:</b> C20 lower/D2.R/R28.2 is separate from U3 pin 3 (1.023 Mohm measured). The earlier C19+C20 parallel 200-pF rationale is superseded; both individual 100pF* estimates remain provisional. RX-1/RX-2 additionally reject C19 lower-to-U3.3 and C20 upper-to-GND; the new owner reports resolve their destinations: C19 lower joins C20 lower/R28 right/D2.R, C20 upper joins R42 lower/D3.S, and U3 pin3 joins VREF. C19 and C20 share only one node and are not parallel. CurrentEvidence properties and the current net column qualify the original proposal rationale. <a href="../evidence/receiver_input_results_20261015.json">Recorded connectivity measurements</a>. <b>No new capacitor-value measurements are requested.</b> RX-1 (C19 lower to U3 pin 3) and RX-2 (C20 upper to GND) were the only connectivity readings requested in the reviewed round; both are now completed and must not be repeated. Connectivity follow-up is separate from capacitor-value work: see the <a href="FINISHING_MEASUREMENTS.html">current measurement guide</a> for the current status and recorded photo locations. RX-3 is deferred by owner request; no readings are pending.</div>'
page+=section('134.2 kHz, with five tuning controls','''<p>PetSafe's page selected for SKU PPA19-16811 lists FDX-B compatibility and explains the 134.2-kHz frequency. This gives a justified design target; the actual carrier on this PCB has not been measured. Different supported pet identities do not require five distinct carrier frequencies. <a href="#src-PETSAFE">Manufacturer reference</a></p><p><b>My leading explanation is a tunable resonant bank</b> compensating for coil tolerance, component spread and installation detuning. Five independent binary controls permit up to 32 switch states. Near-binary effective capacitance is a useful design choice, but neither those weights nor automatic calibration is proven here. Equal or mixed coarse/fine weights could produce fewer distinct resonances. <a href="#src-TI_LF">LF switched-trimming example</a></p>''')
page+=section('Low supply voltage does not bound antenna voltage',''.join('<p>'+e(p['voltage_review'][key])+'</p>' for key in ['supply','resonance','bank_selection','size'])+'<p><a href="#src-RF_Q">Resonance and voltage magnification</a> | <a href="#src-MURATA">Size and selection</a> | <a href="#src-BIAS">DC-bias effects</a></p>')
diagram='''<svg viewBox="0 0 770 245" role="img" aria-label="One idealized branch: Ca from ANT2 to midpoint; Cg from midpoint to ground; Cs and switch from midpoint to ground"><g stroke="#21594c" stroke-width="3" fill="none"><path d="M35 70H180 M192 70H390V180H448 M180 49V91 M192 49V91 M390 70H535 M547 70H710V180H655 M535 49V91 M547 49V91 M448 159V201 M460 159V201 M460 180H555 M555 180L603 151 M611 180H655 M655 180V215 M635 215H675 M641 223H669 M647 231H663"/></g><circle cx="390" cy="70" r="5" fill="#21594c"/><circle cx="655" cy="180" r="5" fill="#21594c"/><g fill="#193d35" font-size="18"><text x="35" y="45">ANT2</text><text x="166" y="30">Ca</text><text x="370" y="40">MID</text><text x="523" y="30">Cg</text><text x="438" y="142">Cs</text><text x="535" y="125">Ideal switch</text></g></svg>'''
antenna_rows=[[str(x['inductance_uh'])+' uH',f'{x["equivalent_capacitance_nf"]:.2f} nF'] for x in p['calculations']['antenna_examples']]
branch_rows=[[f'{x["branch"]} / {x["switch"]}',x['antenna_cap']+' = 1 nF',x['ground_cap']+' = 1 nF',f'{x["switched_cap"]} = {x["switched_pf"]:g} pF',f'{x["increment_pf"]:.1f} pF'] for x in b['branches']]
body='''<p><b>Antenna: 500 uH, now reported measured by the owner.</b> The earlier design assumption matches this report. Test frequency, isolation from the PCB, instrument and losses were not specified. It needs about 2.813 nF equivalent capacitance at 134.2 kHz. This supports the total capacitance scale, not the 15 individual values or their weights. <a href="../evidence/antenna_inductance_results_20261015.json">Measurement record</a></p><p>For comparison, other coil inductances would require:</p>'''+table(['Illustrative inductance','Equivalent capacitance at 134.2 kHz'],antenna_rows)
body+='''<p>Each existing branch contains three capacitors. Ca joins ANT2 to its midpoint; Cg joins that midpoint to ground; Cs joins it to the transistor. The equations below assume the transistor is an ideal open/closed ground switch. The disputed transistor identity does not establish that AC behavior.</p>'''+diagram+'''<p><code>Coff = Ca × Cg / (Ca + Cg)</code><br><code>Con = Ca × (Cg + Cs) / (Ca + Cg + Cs)</code></p><p>Choose Ca = Cg = 1 nF in each branch. Choose Cs to add roughly 25, 50, 100, 200 and 400 pF of <em>equivalent</em> capacitance. Cs values themselves are not a 1:2:4:8:16 sequence because of the series/parallel network.</p>'''+table(['Branch / switch','Ca: antenna side','Cg: rear ground side','Cs: switched side','Calculated addition'],branch_rows)
best=b['nearest_state']
body+=f'<p>The example spans {b["states"][0]["equivalent_pf"]/1000:.3f} to {b["states"][-1]["equivalent_pf"]/1000:.3f} nF. With 500 uH, mask {best["mask"]} ({e(" + ".join(best["switches_closed"]))} ideally closed) gives {best["equivalent_pf"]/1000:.3f} nF and {best["frequency_khz"]:.3f} kHz. This is mathematical consistency, not evidence of the factory values or firmware codes.</p>'
def x(mask): return 65+mask*22
def y(f): return 220-(f-120)*7
chart='<svg viewBox="0 0 800 275" role="img" aria-label="Calculated frequencies for 32 ideal switch states using the user-reported 500 microhenry coil">'
for f in [120,125,130,135,140,145]: chart+=f'<path d="M65 {y(f)}H755" stroke="#dae5df"/><text x="22" y="{y(f)+5}" font-size="13">{f}</text>'
chart+=f'<path d="M65 {y(134.2)}H755" stroke="#b65c16" stroke-dasharray="5 4"/><text x="520" y="{y(134.2)-8}" font-size="14" fill="#93460e">Target 134.2 kHz</text>'
for s in b['states']: chart+=f'<circle cx="{x(s["mask"])}" cy="{y(s["frequency_khz"])}" r="4" fill="#126651"><title>Mask {s["mask"]}: {s["frequency_khz"]:.3f} kHz; {s["equivalent_pf"]:.1f} pF</title></circle>'
for mask in [0,4,8,12,16,20,24,28,31]: chart+=f'<text x="{x(mask)-7}" y="243" font-size="13">{mask}</text>'
chart+='<text x="18" y="22" font-size="14">kHz</text><text x="250" y="268" font-size="14">Design-example switch mask (not firmware codes)</text></svg>'
body+=chart+'<p class="caption">Calculated states only. Parasitics, detector loading, losses and transistor conduction omitted. Ascending weights assigned to physical branches are arbitrary design choices.</p><p>'+e(b['scaling'])+'</p><p><b>The roughly 5-ohm winding resistance does not establish inductance. L1/L2 are supply filters and are not the coil in this equation.</b></p>'
page+=section('A coherent RF design seed, not fifteen independent guesses',body)
page+=section('Receiver and timing choices','''<p>C21/C22 = 220 pF gives a 6.03-kHz isolated feedback pole with each 120-kohm resistor. C23 = 47 nF gives an approximate 498-Hz coupling corner with 6.8 kohm. C18 + C25 = 3.2 nF gives a 4.97-kHz output-filter pole if VREF is AC-stiff. These are linked starting choices for an envelope/baseband path, not a verified complete receiver transfer function.</p><p>The six fitted C21/C22 readings were 680/340/240 pF and 680/320/240 pF at 1/10/100 kHz. Mode was C/Auto or unsure; D was absent. They support only a rough pF scale. C8/C9 = 100 pF gives nominal RC products of 0.12/0.18 us, but U2 thresholds, diode paths and Q8 waveforms decide whether the timing is usable. The C19/C20 parallel allocation is superseded by the measured receiver split; the C40/C41 allocation remains a low-confidence proposal, not identifiable originals.</p>''')
for key,title in groups:
    rows=[]
    for c in p['components']:
        if c['category']!=key: continue
        links=' '.join('<a href="#src-'+e(s)+'">'+e(s)+'</a>' for s in c['sources'])
        qualified=c['ref'] in {'C19','C20'}
        nets=[current_nets.get(c['ref']+'.'+str(pin),'unassigned') for pin in [1,2]]
        function='Receiver branch; exact role qualified after measured input-node split' if qualified else c['function']
        basis=('Superseded pre-split rationale (not a current parallel-network claim): ' if qualified else '')+c['basis']
        rows.append([f'<b id="{c["ref"]}">{c["ref"]}</b><br><small>'+e(c['footprint'].split(':')[-1])+'</small>',e(function)+'<br><small>'+e(' / '.join(nets))+'</small>',f'<b>{e(c["proposal"])}</b><br>{c["voltage_rating_v"]} V / {e(c["dielectric"])}<br>Tolerance: {c["tolerance_percent"]}%<br><small>{e(c["confidence"])}</small>',e(basis)+'<br>'+links,e(c['remaining'])])
    page+=section(title,table(['Part','Function / modeled nets','Chosen candidate','Reason','Still to qualify'],rows))
page+=section('Established capacitor and unpopulated options','<p><b>C5: 470 uF, 16 V aluminium electrolytic.</b> Retain the known value and measured 6.33-mm diameter / 16-mm height.</p><p><b>'+', '.join(c['ref'] for c in p['unpopulated_capacitors'])+': DNP.</b> Keep all six options unpopulated. No fitted value needs guessing. C49 remains the empty ANT2-to-GND option.</p>')
page+=section('How to validate efficiently later','<ol>'+''.join('<li>'+e(x)+'</li>' for x in p['next_actions'])+'</ol>')
page+=section('Evidence boundaries','<ul>'+''.join('<li>'+e(x)+'</li>' for x in p['principles'])+'</ul>')
page+=section('Primary references','<ul>'+''.join('<li id="src-'+e(s['id'])+'"><a href="'+e(s['url'],quote=True)+'">'+e(s['title'])+'</a>: '+e(s['finding'])+'</li>' for s in p['sources'])+'</ul>')
page+='<p><a href="../evidence/capacitor_value_review_20261015.json">Machine-readable choices, ratings and 32 calculated states</a> | <a href="../evidence/receiver_capacitance_results_20261015.json">Raw fitted measurements</a></p></html>'
(R/'docs/CAPACITOR_VALUE_REVIEW.html').write_text(page,encoding='utf-8')
print('Complete capacitor candidates:',dict(Counter(c['category'] for c in p['components'])))
